package org.apache.commons.lang.math;

import junit.framework.TestCase;

public class AgentBRT_Lang_58_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        // Test case for a small number with a type qualifier 'D'
        String input = "4.9E-324D"; // Close to Double.MIN_VALUE
        try {
            Number result = NumberUtils.createNumber(input);
            assertTrue("Expected a Double instance", result instanceof Double);
            assertEquals("Expected value close to Double.MIN_VALUE", 4.9E-324, result.doubleValue(), 0.0);
        } catch (NumberFormatException e) {
            fail("NumberFormatException was thrown for a valid double string with 'D' qualifier");
        }
    }
}

