package org.apache.commons.lang.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_58_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Test case for a string with a type qualifier 'F'
        String input = "123.45F";
        try {
            Number result = NumberUtils.createNumber(input);
            assertTrue("Expected a Float instance", result instanceof Float);
            assertEquals("Expected value 123.45", 123.45f, result.floatValue(), 0.0f);
        } catch (NumberFormatException e) {
            fail("NumberFormatException was thrown for a valid float string with 'F' qualifier");
        }
    }
}

